/**
 * Purchase (expense) PDF
 * © Liamarjit Bhogal (© Seva Cloud 2026)
 *
 * QuickFile's API only renders PDFs for sales invoices, so expenses get an
 * A4 summary built here from the purchase as QuickFile stored it. It says
 * plainly that it was generated by the trustee portal, not by QuickFile.
 *
 * Uses pdf-lib's built-in Helvetica (WinAnsi encoding): characters it
 * can't encode are replaced rather than failing the whole document.
 */

import 'server-only';
import { PDFDocument, StandardFonts, rgb, type PDFFont, type PDFPage } from 'pdf-lib';
import type { SubmittedRecord } from './submissions';
import { formatDate, formatGBP } from './format';
import { statusLabel } from './status';

const ORG_NAME = 'Upper Wincobank Chapel';
const A4: [number, number] = [595.28, 841.89];
const MARGIN = 50;
const GREY = rgb(0.4, 0.4, 0.4);
const RULE = rgb(0.85, 0.85, 0.85);

export async function buildPurchasePdf(p: { id: number; number: string; supplierName: string; record: SubmittedRecord }): Promise<Uint8Array> {
  const doc = await PDFDocument.create();
  doc.setTitle(`Purchase ${p.number}`);
  doc.setAuthor(ORG_NAME);
  doc.setProducer('Wincobank Chapel trustee portal');

  const regular = await doc.embedFont(StandardFonts.Helvetica);
  const bold = await doc.embedFont(StandardFonts.HelveticaBold);
  const safe = (font: PDFFont, text: string) =>
    Array.from(text).map((ch) => { try { font.encodeText(ch); return ch; } catch { return '?'; } }).join('');

  let page: PDFPage = doc.addPage(A4);
  const width = A4[0] - MARGIN * 2;
  let y = A4[1] - MARGIN;

  const ensure = (h: number) => {
    if (y - h < MARGIN + 30) { page = doc.addPage(A4); y = A4[1] - MARGIN; }
  };
  const text = (s: string, x: number, opts: { font?: PDFFont; size?: number; color?: ReturnType<typeof rgb>; right?: boolean } = {}) => {
    const font = opts.font ?? regular;
    const size = opts.size ?? 10;
    const str = safe(font, s);
    const dx = opts.right ? x - font.widthOfTextAtSize(str, size) : x;
    page.drawText(str, { x: dx, y, size, font, color: opts.color ?? rgb(0, 0, 0) });
  };
  const wrap = (s: string, font: PDFFont, size: number, max: number): string[] => {
    const lines: string[] = [];
    for (const para of safe(font, s).split('\n')) {
      let line = '';
      for (const word of para.split(/\s+/)) {
        const next = line ? `${line} ${word}` : word;
        if (font.widthOfTextAtSize(next, size) <= max || !line) line = next;
        else { lines.push(line); line = word; }
      }
      lines.push(line);
    }
    return lines;
  };
  const rule = () => page.drawLine({ start: { x: MARGIN, y }, end: { x: MARGIN + width, y }, thickness: 0.5, color: RULE });

  // Header
  text(ORG_NAME, MARGIN, { font: bold, size: 11, color: GREY });
  y -= 28;
  text(`Purchase ${p.number}`, MARGIN, { font: bold, size: 20 });
  text(formatGBP(p.record.total), MARGIN + width, { font: bold, size: 20, right: true });
  y -= 30;

  // Details, two columns
  const r = p.record;
  const details: Array<[string, string]> = [
    ['Supplier', p.supplierName || '—'],
    ['Receipt date', r.date ? formatDate(r.date) : '—'],
    ...(r.dueDate ? [['Due date', formatDate(r.dueDate)] as [string, string]] : []),
    ['Receipt / invoice number', r.reference || '—'],
    ['Description', r.description || '—'],
    ['Project', r.tags.join(', ') || '—'],
    ['Status', statusLabel(r.status)],
  ];
  const colW = width / 2;
  for (let i = 0; i < details.length; i += 2) {
    ensure(30);
    details.slice(i, i + 2).forEach(([label, value], c) => {
      const x = MARGIN + c * colW;
      text(label, x, { size: 8, color: GREY });
      y -= 12;
      text(wrap(value, regular, 10, colW - 12)[0], x);
      y += 12;
    });
    y -= 30;
  }

  // Lines
  const amountX = MARGIN + width;
  const categoryX = MARGIN + width * 0.55;
  const descW = width * 0.55 - 12;
  const catW = width * 0.3 - 12;
  ensure(40);
  y -= 6;
  text('Description', MARGIN, { font: bold, size: 9 });
  text('Category', categoryX, { font: bold, size: 9 });
  text('Amount', amountX, { font: bold, size: 9, right: true });
  y -= 6;
  rule();
  y -= 14;

  for (const l of r.lines) {
    const desc = wrap(l.description || '—', regular, 9, descW);
    const cat = wrap(l.nominalName ? `${l.nominalCode} ${l.nominalName}` : String(l.nominalCode), regular, 9, catW);
    const rows = Math.max(desc.length, cat.length);
    ensure(rows * 12 + 10);
    text(formatGBP(l.total), amountX, { size: 9, right: true });
    for (let i = 0; i < rows; i++) {
      if (desc[i]) text(desc[i], MARGIN, { size: 9 });
      if (cat[i]) text(cat[i], categoryX, { size: 9 });
      y -= 12;
    }
    y += 4;
    rule();
    y -= 14;
  }

  ensure(30);
  text('Total', categoryX, { font: bold, size: 10 });
  text(formatGBP(r.total), amountX, { font: bold, size: 10, right: true });

  // Footer on every page
  const generated = formatDate(new Date().toISOString().slice(0, 10));
  doc.getPages().forEach((pg, i, all) => {
    const note = safe(regular, `Generated by the ${ORG_NAME} trustee portal on ${generated} from QuickFile purchase ${p.number} (ID ${p.id}). Not a QuickFile document.`);
    pg.drawText(note, { x: MARGIN, y: MARGIN - 10, size: 7, font: regular, color: GREY });
    const pn = `Page ${i + 1} of ${all.length}`;
    pg.drawText(pn, { x: MARGIN + width - regular.widthOfTextAtSize(pn, 7), y: MARGIN - 22, size: 7, font: regular, color: GREY });
  });

  return doc.save();
}
